local KEY_DUNG = "chan1bo2may3deVVV3667"
local URL = "https://raw.githubusercontent.com/noname-new/RobloxScript/refs/heads/main/scriptRBL/loader"

local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")

local player = Players.LocalPlayer

local gui = Instance.new("ScreenGui")
gui.Name = "KeySystem"
gui.ResetOnSpawn = false
gui.Parent = player:WaitForChild("PlayerGui")

local khung = Instance.new("Frame")
khung.Size = UDim2.new(0, 320, 0, 175)
khung.Position = UDim2.new(0.5, -160, 0.5, -87)
khung.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
khung.BorderColor3 = Color3.fromRGB(255, 255, 255)
khung.BorderSizePixel = 1
khung.Active = true
khung.Parent = gui

-- Tiêu đề
local tieuDe = Instance.new("TextLabel")
tieuDe.Size = UDim2.new(1, -45, 0, 35)
tieuDe.Position = UDim2.new(0, 10, 0, 8)
tieuDe.BackgroundTransparency = 1
tieuDe.Text = " KEY SYSTEM"
tieuDe.TextColor3 = Color3.new(1, 1, 1)
tieuDe.TextSize = 16
tieuDe.Font = Enum.Font.GothamBold
tieuDe.Parent = khung

-- Nút X đóng giao diện
local nutX = Instance.new("TextButton")
nutX.Size = UDim2.new(0, 28, 0, 28)
nutX.Position = UDim2.new(1, -33, 0, 5)
nutX.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
nutX.BorderColor3 = Color3.new(1, 1, 1)
nutX.BorderSizePixel = 1
nutX.Text = "X"
nutX.TextColor3 = Color3.new(1, 1, 1)
nutX.TextSize = 16
nutX.Font = Enum.Font.GothamBold
nutX.Parent = khung

nutX.MouseButton1Click:Connect(function()
    gui:Destroy()
end)

-- Ô nhập key
local oNhap = Instance.new("TextBox")
oNhap.Size = UDim2.new(1, -30, 0, 38)
oNhap.Position = UDim2.new(0, 15, 0, 53)
oNhap.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
oNhap.BorderColor3 = Color3.new(1, 1, 1)
oNhap.BorderSizePixel = 1
oNhap.PlaceholderText = "Nhập key tại đây..."
oNhap.PlaceholderColor3 = Color3.fromRGB(160, 160, 160)
oNhap.Text = ""
oNhap.TextColor3 = Color3.new(1, 1, 1)
oNhap.TextSize = 14
oNhap.Font = Enum.Font.Gotham
oNhap.ClearTextOnFocus = false
oNhap.Parent = khung

-- Nút xác nhận
local xacNhan = Instance.new("TextButton")
xacNhan.Size = UDim2.new(1, -30, 0, 35)
xacNhan.Position = UDim2.new(0, 15, 0, 103)
xacNhan.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
xacNhan.BorderColor3 = Color3.new(1, 1, 1)
xacNhan.BorderSizePixel = 1
xacNhan.Text = "XÁC NHẬN"
xacNhan.TextColor3 = Color3.new(1, 1, 1)
xacNhan.TextSize = 14
xacNhan.Font = Enum.Font.GothamBold
xacNhan.Parent = khung

-- Thông báo
local thongBao = Instance.new("TextLabel")
thongBao.Size = UDim2.new(1, -20, 0, 20)
thongBao.Position = UDim2.new(0, 10, 1, -21)
thongBao.BackgroundTransparency = 1
thongBao.Text = ""
thongBao.TextColor3 = Color3.fromRGB(255, 80, 80)
thongBao.TextSize = 12
thongBao.Font = Enum.Font.Gotham
thongBao.Parent = khung

-- Kéo khung bằng chuột hoặc cảm ứng
local dangKeo = false
local viTriDau
local viTriKhung

khung.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then

        -- Không bắt đầu kéo khi bấm vào ô nhập hoặc các nút
        local pos = input.Position
        local objects = player.PlayerGui:GetGuiObjectsAtPosition(pos.X, pos.Y)

        for _, obj in ipairs(objects) do
            if obj == nutX or obj == oNhap or obj == xacNhan then
                return
            end
        end

        dangKeo = true
        viTriDau = input.Position
        viTriKhung = khung.Position
    end
end)

UserInputService.InputChanged:Connect(function(input)
    if dangKeo and (
        input.UserInputType == Enum.UserInputType.MouseMovement
        or input.UserInputType == Enum.UserInputType.Touch
    ) then
        local delta = input.Position - viTriDau

        khung.Position = UDim2.new(
            viTriKhung.X.Scale,
            viTriKhung.X.Offset + delta.X,
            viTriKhung.Y.Scale,
            viTriKhung.Y.Offset + delta.Y
        )
    end
end)

UserInputService.InputEnded:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
        dangKeo = false
    end
end)

-- Kiểm tra key
local dangChay = false

local function kiemTraKey()
    if dangChay then
        return
    end

    if oNhap.Text == KEY_DUNG then
        dangChay = true
        thongBao.TextColor3 = Color3.fromRGB(100, 255, 100)
        thongBao.Text = "Key chính xác!"

        task.wait(0.3)
        gui:Destroy()

        local thanhCong, loi = pcall(function()
            loadstring(game:HttpGet(URL))()
        end)

        if not thanhCong then
            warn("Lỗi chạy loader: " .. tostring(loi))
        end
    else
        thongBao.TextColor3 = Color3.fromRGB(255, 80, 80)
        thongBao.Text = "Key không chính xác!"
        oNhap.Text = ""
    end	
end

xacNhan.MouseButton1Click:Connect(kiemTraKey)

oNhap.FocusLost:Connect(function(enterPressed)
    if enterPressed then
        kiemTraKey()
    end
end)
